const email = process.env.NERJA_EMAIL;
const password = process.env.NERJA_PASSWORD;
if (!email || !password) throw new Error('Set NERJA_EMAIL and NERJA_PASSWORD env vars');
return [{ json: { baseUrl: 'https://dev.nerja.ai', email, password, tests: [] } }];

const r = $json;
const cfg = $('Test Config').first().json;
const ok = r.statusCode === 200 && r.body && r.body.user && r.body.user.email === cfg.email;
const cookie = r.headers && r.headers['set-cookie'] ? (Array.isArray(r.headers['set-cookie']) ? r.headers['set-cookie'].join('; ') : r.headers['set-cookie']) : '';
return [{ json: { ...cfg, sessionCookie: cookie, tests: [...cfg.tests, { id: 'T1', name: 'Valid Login', passed: ok, expected: 'HTTP 200 + user.email in body', actual: 'HTTP ' + r.statusCode, detail: ok ? '✅ Valid credentials accepted' : '❌ Login failed — got ' + r.statusCode }] } }];

const r = $json;
const prev = $('Eval T1').first().json;
const ok = r.statusCode !== 200;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'T2', name: 'Wrong Password Rejected', passed: ok, expected: 'HTTP 4xx (not 200)', actual: 'HTTP ' + r.statusCode, detail: ok ? '✅ Wrong password correctly rejected' : '❌ Server accepted wrong password!' }] } }];

const r = $json;
const prev = $('Eval T2').first().json;
const ok = r.statusCode !== 200;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'T3', name: 'Nonexistent Email Rejected', passed: ok, expected: 'HTTP 4xx (not 200)', actual: 'HTTP ' + r.statusCode, detail: ok ? '✅ Unknown email correctly rejected' : '❌ Server accepted unknown email!' }] } }];

const r = $json;
const prev = $('Eval T3').first().json;
const ok = r.statusCode !== 200;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'T4', name: 'Empty Email Rejected', passed: ok, expected: 'HTTP 4xx (not 200)', actual: 'HTTP ' + r.statusCode, detail: ok ? '✅ Empty email correctly rejected' : '❌ Server accepted empty email!' }] } }];

const r = $json;
const prev = $('Eval T4').first().json;
const ok = r.statusCode !== 200;
return [{ json: { ...prev, tests: [...prev.tests, { id: 'T5', name: 'Empty Password Rejected', passed: ok, expected: 'HTTP 4xx (not 200)', actual: 'HTTP ' + r.statusCode, detail: ok ? '✅ Empty password correctly rejected' : '❌ Server accepted empty password!' }] } }];

const r = $json;
const prev = $('Eval T5').first().json;
const location = (r.headers && (r.headers['location'] || r.headers['Location'])) || '';
const ok = r.statusCode !== 200 || location.includes('login');
return [{ json: { ...prev, tests: [...prev.tests, { id: 'T6', name: 'Unauthenticated Dashboard Protected', passed: ok, expected: 'Redirect to /login or HTTP 401', actual: 'HTTP ' + r.statusCode + (location ? ' → ' + location : ''), detail: ok ? '✅ Dashboard requires authentication' : '❌ Dashboard accessible without auth!' }] } }];

const data = $('Eval T6').first().json;
const tests = data.tests || [];
const passed = tests.filter(t => t.passed).length;
const failed = tests.filter(t => !t.passed).length;
console.log('\n╔══════════════════════════════════╗');
console.log('║  NERJA AI — AUTH TESTS RESULTS   ║');
console.log('╚══════════════════════════════════╝');
tests.forEach(t => console.log(t.detail));
console.log('\n→ ' + passed + '/' + tests.length + ' passed | ' + failed + ' failed');
return [{ json: { suite: '01 Auth Tests', total: tests.length, passed, failed, status: failed === 0 ? 'PASS' : 'FAIL', tests, timestamp: new Date().toISOString() } }];
